test('V17.7.3 service — AGGREGATION: unique users are NOT multiplied by sessions; DAU / WAU / MAU, sessions, active time, generations, success rate, daily / weekly / monthly rows, features and versions are exact', async () => DONE(await world(), async (w) => {
  // the service buckets by the time it RECEIVES the events (a client clock more than 7 days off is ignored), so the "days" below are produced by moving the service clock
  const at = async (d, h, list) => { w.clock.t = Date.parse(`${d}T${String(h).padStart(2, '0')}:00:00Z`); const r = await w.events(list.map(({ dt = 0, ...e }) => ({ ...e, ts: w.clock.t + dt }))); assert.equal(r.json.rejected, 0, JSON.stringify(r.json)); return r; };
  // user A: three sessions on three days (the SAME device id) — one unique user
  await at('2026-10-20', 10, [ev({ uid: UID_B, sid: sid(5), ver: '17.7.2' })]);
  await at('2026-11-02', 10, [ev({ uid: UID_A, sid: sid(1) }), ev({ t: 'active', uid: UID_A, sid: sid(1), dt: 60_000, ms: 60_000 }), ev({ t: 'feature', f: 'quick-start', uid: UID_A, sid: sid(1) })]);
  await at('2026-11-05', 10, [ev({ uid: UID_A, sid: sid(2) }), ev({ t: 'active', uid: UID_A, sid: sid(2), dt: 120_000, ms: 120_000 }), ev({ t: 'generation', k: 'describe-read-only', ok: true, uid: UID_A, sid: sid(2) })]);
  await at('2026-11-09', 10, [ev({ uid: UID_A, sid: sid(3) }), ev({ t: 'active', uid: UID_A, sid: sid(3), dt: 30_000, ms: 30_000 }), ev({ t: 'generation', k: 'cr', ok: false, uid: UID_A, sid: sid(3) }), ev({ t: 'generation', k: 'read-only', ok: true, rv: true, uid: UID_A, sid: sid(3) }),
    ev({ uid: UID_B, sid: sid(4), ver: '17.7.2' }), ev({ t: 'active', uid: UID_B, sid: sid(4), ver: '17.7.2', dt: 90_000, ms: 90_000 }), ev({ t: 'feature', f: 'about', uid: UID_B, sid: sid(4), ver: '17.7.2' }), ev({ t: 'feature', f: 'quick-start', uid: UID_B, sid: sid(4), ver: '17.7.2' })]);
  w.clock.t = T0; const t = await w.token(); const r = (await w.summary(t, '?from=2026-11-01&to=2026-11-09')).json; const k = r.kpi;
  assert.equal(k.uniqueUsers, 2, 'user A had THREE sessions and is ONE unique user'); assert.equal(k.totalSessions, 4); assert.equal(k.totalActiveMs, 300_000); assert.equal(k.averageActiveMsPerSession, 75_000); assert.equal(k.averageActiveMsPerUser, 150_000);
  assert.equal(k.dailyActiveUsers, 2, 'both on 2026-11-09'); assert.equal(k.weeklyActiveUsers, 2); assert.equal(k.monthlyActiveUsers, 2, 'the 30 days to 2026-11-09 include 2026-10-20'); assert.equal(r.range.referenceDay, '2026-11-09'); assert.equal(r.range.timezone, 'UTC');
  assert.deepEqual([k.generated, k.successful, k.failed, k.needsReview, k.successRate], [3, 2, 1, 1, 66.7]);
  assert.equal(r.daily.length, 9); assert.equal(r.daily[0].date, '2026-11-01'); const d9 = r.daily.at(-1); assert.deepEqual([d9.date, d9.users, d9.sessions, d9.activeMs, d9.generations, d9.success, d9.failure], ['2026-11-09', 2, 2, 120_000, 2, 1, 1]); assert.equal(r.daily[0].sessions, 0, 'days without usage are present (zero) so a chart has no gaps');
  assert.deepEqual(r.weekly.map((x) => [x.weekStart, x.users, x.sessions, x.days]), [['2026-10-26', 0, 0, 1], ['2026-11-02', 1, 2, 7], ['2026-11-09', 2, 2, 1]], 'weeks start on Monday and are clipped to the range (2026-11-01 is a Sunday: the first week has one day in range)'); assert.deepEqual(r.monthly.map((x) => [x.month, x.users, x.sessions, x.activeMs]), [['2026-11', 2, 4, 300_000]]);
  assert.deepEqual(r.features, [{ id: 'quick-start', count: 2 }, { id: 'about', count: 1 }]); assert.deepEqual(r.versions, [{ version: '17.7.3', sessions: 3, users: 1 }, { version: '17.7.2', sessions: 1, users: 1 }]);
  // a wider range now includes the 2026-10-20 session of user B (the same user as on 2026-11-09 → still 2 unique users)
  const wide = (await w.summary(t, '?from=2026-10-01&to=2026-11-09')).json; assert.equal(wide.kpi.uniqueUsers, 2); assert.equal(wide.kpi.totalSessions, 5); assert.deepEqual(wide.monthly.map((x) => [x.month, x.users]), [['2026-10', 1], ['2026-11', 2]]);
  const day1 = (await w.summary(t, '?from=2026-11-09&to=2026-11-09')).json; assert.equal(day1.kpi.uniqueUsers, 2); assert.equal(day1.daily.length, 1);
  const past = (await w.summary(t, '?from=2026-11-01&to=2026-11-05')).json; assert.equal(past.range.referenceDay, '2026-11-05'); assert.equal(past.kpi.dailyActiveUsers, 1, 'DAU is relative to the end of the range'); assert.equal(past.kpi.uniqueUsers, 1);
  assert.equal((await w.summary(t, '?from=2026-11-09&to=2026-11-01')).status, 400); assert.equal((await w.summary(t, '?from=2026-13-40&to=2026-11-01')).status, 400); assert.equal((await w.summary(t, '?from=2020-01-01&to=2026-11-09')).json.error, 'range-too-large');
  const dflt = (await w.summary(t)).json; assert.equal(dflt.range.days, 30); assert.equal(dflt.range.to, '2026-11-09', 'default range: the last 30 days');
}));
