test('V17.7.3 service — active time cannot exceed the time that really passed in the session; a repeated session id never creates a second session; a session that continues after a restart is not counted again', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sqla-an-')); let w = await world({ dataDir: dir });
  try {
    await w.events([ev({ sid: sid(21), ts: T0 })]); const r1 = await w.events([ev({ t: 'active', sid: sid(21), ts: T0 + 60_000, ms: 600_000 })]); assert.equal(r1.json.accepted, 1, 'the claim is trimmed, not an error'); const t1 = await w.token(); const k1 = (await w.summary(t1, '?from=2026-11-09&to=2026-11-09')).json.kpi; assert.equal(k1.totalActiveMs, 150_000, 'at most 60 s since the start + 90 s of tolerance'); assert.equal(k1.totalSessions, 1);
    const r2 = await w.events([ev({ t: 'active', sid: sid(21), ts: T0 + 60_000, ms: 600_000 })]); assert.equal(r2.json.rejected, 1, 'nothing left to claim'); assert.equal((await w.summary(t1, '?from=2026-11-09&to=2026-11-09')).json.kpi.totalActiveMs, 150_000);
    await w.events([ev({ sid: sid(21), ts: T0 + 5000 })]); assert.equal((await w.summary(t1, '?from=2026-11-09&to=2026-11-09')).json.kpi.totalSessions, 1, 'a second session_start of the same session id is not a new session');
    w.svc.flush(); await w.svc.close(); w = await world({ dataDir: dir }); await w.events([ev({ t: 'feature', f: 'about', sid: sid(21), ts: T0 + 20_000 })]); const t2 = await w.token(); const k2 = (await w.summary(t2, '?from=2026-11-09&to=2026-11-09')).json.kpi; assert.equal(k2.totalSessions, 1, 'restart: the same session is not counted twice'); assert.equal(k2.totalActiveMs, 150_000, 'restart: the data was kept'); assert.equal(k2.uniqueUsers, 1);
  } finally { await w.close(); rmSync(dir, { recursive: true, force: true }); }
});
test('V17.7.3 service — the store keeps only per-day roll-ups: no event content, no free text, the data of older days is dropped after the retention period', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sqla-an-')); let w = await world({ dataDir: dir, env: { SQLA_ANALYTICS_RETENTION_DAYS: '30' } });
  try {
    await w.events([ev({ sid: sid(31), ts: T0 }), ev({ t: 'generation', k: 'cr', ok: true, sid: sid(31), ts: T0 })]); w.svc.flush(); const stored = JSON.parse(readFileSync(join(dir, 'analytics-store.json'), 'utf8')); assert.deepEqual(Object.keys(stored).sort(), ['days', 'format', 'formatVersion', 'salt', 'sessions']); assert.deepEqual(Object.keys(stored.days['2026-11-09']).sort(), ['activeMs', 'features', 'gen', 'sessions', 'users', 'versions']);
    const flat = JSON.stringify(stored); assert.ok(!/eid|"ts"|"sql"|description/i.test(flat), 'no event, no timestamp of an event, no text field'); if (process.platform !== 'win32') assert.equal(statSync(join(dir, 'analytics-store.json')).mode & 0o077, 0, 'the store file is private to the service user');
    await w.svc.close(); const later = await world({ dataDir: dir, env: { SQLA_ANALYTICS_RETENTION_DAYS: '30' } }); try { later.clock.t = T0 + 40 * DAY; later.svc._store(); /* prune runs at start-up; a new service far in the future prunes on creation */ } finally { await later.close(); }
    const w3 = SV.createAnalyticsService({ SQLA_ANALYTICS_ALLOWED_ORIGINS: ORIGIN, SQLA_ANALYTICS_RETENTION_DAYS: '30', SQLA_ANALYTICS_ADMIN_PASSWORD: PW }, { dataDir: mkdtempSync(join(tmpdir(), 'sqla-an-')), now: () => T0 + 40 * DAY, kdf: FAST, auditSink: () => {} }); try { assert.deepEqual(Object.keys(w3._store().days), []); } finally { await w3.close(); }
  } finally { try { await w.close(); } catch { /* closed */ } rmSync(dir, { recursive: true, force: true }); }
});

