  const d = on({}); assert.equal(d.state, 'enabled'); assert.deepEqual(d.config, { enabled: true, provider: 'service', serviceUrl: 'https://an.example.org', inactivityTimeout: 300, collectUserIdentity: false, applicationVersion: F.APP_VERSION, adminAuthenticationEnabled: true, adminSessionTimeout: 900 });
  assert.equal(CFG.parseAnalyticsConfig(JSON.stringify({ 'analytics.enabled': true, 'analytics.serviceUrl': 'https://flat.example.org', 'analytics.inactivityTimeout': 120, 'analytics.collectUserIdentity': true, 'analytics.adminSessionTimeout': 600 })).config.inactivityTimeout, 120); assert.equal(CFG.parseAnalyticsConfig(JSON.stringify({ 'analytics.enabled': true, 'analytics.serviceUrl': 'https://flat.example.org', 'analytics.collectUserIdentity': true })).config.collectUserIdentity, true);
  assert.equal(on({ inactivityTimeout: 1 }).config.inactivityTimeout, 5); assert.equal(on({ inactivityTimeout: 99999 }).config.inactivityTimeout, 3600); assert.equal(on({ adminSessionTimeout: 1 }).config.adminSessionTimeout, 10); assert.equal(on({ adminSessionTimeout: 10 ** 9 }).config.adminSessionTimeout, 28800); assert.equal(on({ applicationVersion: '17.7.3-rc1' }).config.applicationVersion, '17.7.3-rc1'); assert.equal(on({ applicationVersion: 'auto' }).config.applicationVersion, F.APP_VERSION); assert.equal(on({ adminAuthenticationEnabled: false }).config.adminAuthenticationEnabled, false);
  for (const bad of [{ serviceUrl: 'http://remote.example.org' }, { serviceUrl: 'ftp://x' }, { serviceUrl: 'https://u:p@x.org' }, { serviceUrl: 'https://x.org?q=1' }, { serviceUrl: undefined }, { provider: 'cloud' }, { inactivityTimeout: '300' }, { collectUserIdentity: 'yes' }, { adminAuthenticationEnabled: 1 }, { applicationVersion: 'SELECT *' }, { applicationVersion: 'x'.repeat(40) }]) assert.equal(on(bad).state, 'invalid', JSON.stringify(bad)); assert.equal(on({ serviceUrl: 'http://localhost:8789' }).state, 'enabled', 'http only for localhost');
