// ───────────────────────────────────────── 5. the client: active-use measurement
test('V17.7.3 ActivityMeter — counts only visible + focused + recently-interacting time; pauses when hidden / blurred / idle; resumes only at the next interaction; never double-counts', () => {
  const s = (n) => n * 1000; const m = new TR.ActivityMeter(s(300)); m.start(0, true, true);
  for (let t = 10; t <= 60; t += 10) m.interaction(s(t)); assert.equal(m.drain(s(60)), 60_000, 'continuous interaction for 60 s = 60 s'); assert.equal(m.drain(s(60)), 0, 'nothing is counted twice');
  m.setVisible(false, s(80)); assert.equal(m.drain(s(80)), 20_000, 'up to the moment the tab was hidden'); m.interaction(s(100), true); assert.equal(m.isActive(), false, 'interactions while hidden count for nothing'); assert.equal(m.drain(s(500)), 0, 'the hidden time is NOT active time');
  m.setVisible(true, s(500)); assert.equal(m.isActive(), false, 'visible again — but nothing counts until the user interacts'); assert.equal(m.drain(s(600)), 0); m.interaction(s(600)); m.interaction(s(630)); assert.equal(m.drain(s(630)), 30_000, 'measurement resumed at the interaction');
  m.setFocused(false, s(640)); assert.equal(m.drain(s(640)), 10_000); assert.equal(m.drain(s(900)), 0, 'a window in the background is not active'); m.interaction(s(910), false); assert.equal(m.isActive(), false, 'a mouse move over an unfocused window is not a return'); m.interaction(s(920), true); m.interaction(s(925)); assert.equal(m.drain(s(925)), 5_000, 'a click / key press means the window has focus again');
  const idle = new TR.ActivityMeter(s(300)); idle.start(0, true, true); assert.equal(idle.drain(s(1000)), 300_000, 'idle: at most one inactivity timeout is credited, then the clock stops'); assert.equal(idle.isActive(), false); assert.equal(idle.drain(s(5000)), 0); idle.interaction(s(5000)); assert.equal(idle.drain(s(5020)), 20_000, 'resumes at the next interaction');
  const cut = new TR.ActivityMeter(s(300)); cut.start(0, true, true); cut.interaction(s(100)); cut.setVisible(false, s(150)); assert.equal(cut.drain(s(400)), 150_000);
  const back = new TR.ActivityMeter(s(60)); back.start(s(100), true, true); assert.equal(back.drain(s(50)), 0, 'a clock that jumps back never produces negative or invented time'); const part = new TR.ActivityMeter(s(60)); part.start(0, true, true); assert.equal(part.drain(500, 1000), 0, 'less than a second stays pending'); assert.equal(part.drain(1500, 1000), 1500);
  const hidden = new TR.ActivityMeter(s(60)); hidden.start(0, false, true); assert.equal(hidden.isActive(), false, 'a page opened in a background tab does not count'); hidden.interaction(s(10)); assert.equal(hidden.drain(s(20)), 0);
});
test('V17.7.3 browser binding — listeners: interactions, visibility, focus, page hide; every listener is removed again', async () => {
  const mk = () => { const l = new Map(); return { visibilityState: 'visible', hasFocus: () => true, addEventListener: (t, f) => { (l.get(t) || l.set(t, new Set()).get(t)).add(f); }, removeEventListener: (t, f) => { l.get(t)?.delete(f); }, fire: (t) => [...(l.get(t) || [])].forEach((f) => f()), count: () => [...l.values()].reduce((n, s) => n + s.size, 0) }; };
  const doc = mk(); const win = mk(); let t = 0; const sent = []; const tracker = new TR.AnalyticsTracker({ config: { inactivityTimeout: 300, collectUserIdentity: false, applicationVersion: '17.7.3' }, sink: { send: async (b, o) => { sent.push({ b, o }); return { ok: true }; } }, store: memoryStore(), mono: () => t, wall: () => 1_000_000 + t, identity: () => null });
  let timer = null; const detach = TR.attachBrowserListeners(tracker, { document: doc, window: win, setInterval: (f) => { timer = f; return 1; }, clearInterval: () => { timer = 'cleared'; } }); assert.ok(doc.count() >= 7 && win.count() === 3); assert.equal(tracker.peek()[0].t, 'session_start');
  t = 5000; doc.fire('pointerdown'); t = 8000; doc.fire('keydown'); doc.visibilityState = 'hidden'; doc.fire('visibilitychange'); await new Promise((r) => setTimeout(r, 5)); assert.ok(sent.length === 1 && sent[0].b.some((e) => e.t === 'active' && e.ms === 8000), 'hiding the tab flushes the active time up to that moment'); t = 60_000; doc.visibilityState = 'visible'; doc.fire('visibilitychange'); assert.equal(tracker.stats().active, false, 'visible again — nothing counts until the user interacts'); doc.fire('wheel'); assert.equal(tracker.stats().active, true, 'coming back: the first interaction (here a scroll) resumes the measurement');
  win.fire('pagehide'); await new Promise((r) => setTimeout(r, 5)); assert.ok(sent.at(-1).o.exit === true || sent.length >= 1); detach(); assert.equal(doc.count(), 0); assert.equal(win.count(), 0); assert.equal(timer, 'cleared');
});

// ───────────────────────────────────────── 6. the client: the tracker (metadata only, queue, failure isolation)
const mkTracker = (over = {}) => { const store = over.store || memoryStore(); const clock = { mono: 0, wall: 1_700_000_000_000 }; const sent = []; let result = { ok: true }; const sink = { send: async (batch, o) => { sent.push({ batch: structuredClone(batch), o }); return typeof result === 'function' ? result(batch) : result; } };
  const tr = new TR.AnalyticsTracker({ config: { inactivityTimeout: 300, collectUserIdentity: false, applicationVersion: '17.7.3', ...(over.config || {}) }, sink: over.sink || sink, store, mono: () => clock.mono, wall: () => clock.wall, identity: over.identity || (() => null) }); return { tr, store, clock, sent, set: (r) => { result = r; } }; };
test('V17.7.3 tracker — only metadata is ever queued: session_start, active, feature, generation, session_end — every event has exactly the whitelisted fields; unknown features and kinds are ignored; nothing can carry SQL, text or results', () => {
  const { tr } = mkTracker(); tr.start(true, true); tr.feature('about'); tr.feature('read-only-builder'); tr.feature('SELECT * FROM SECRET_TABLE'); tr.feature(''); tr.feature(null); tr.generation('describe-read-only', true, true); tr.generation('describe-cr', false); tr.generation('select * from t', true); tr.generation(undefined, true);
  const q = tr.peek(); assert.deepEqual(q.map((e) => e.t), ['session_start', 'feature', 'feature', 'generation', 'generation']); const allowed = new Set(['v', 'eid', 't', 'ts', 'uid', 'sid', 'ver', 'usr', 'ms', 'f', 'k', 'ok', 'rv']); for (const e of q) { for (const k of Object.keys(e)) assert.ok(allowed.has(k), k); assert.equal(e.v, 1); assert.match(e.uid, /^[a-f0-9]{32}$/); assert.match(e.sid, /^[a-f0-9]{24}$/); assert.equal(e.ver, '17.7.3'); assert.equal(SV.validateEvent(e, e.ts).ok, true, `the service accepts ${e.t}`); }
  assert.deepEqual([q[3].k, q[3].ok, q[3].rv, q[4].k, q[4].ok, q[4].rv], ['describe-read-only', true, true, 'describe-cr', false, false]); assert.ok(!JSON.stringify(q).match(/SECRET|SELECT/i), 'no text of any kind');
  const API = Object.getOwnPropertyNames(TR.AnalyticsTracker.prototype); assert.deepEqual(API.filter((n) => /sql|text|query|result|schema|password|secret/i.test(n)), [], 'no method of the tracker is named after content');
});
test('V17.7.3 tracker — the device id is created once and kept: the same browser profile is ONE user across sessions; every session has its own session id; the id is random and carries no personal data', () => {
  const store = memoryStore(); const a = mkTracker({ store }); const b = mkTracker({ store }); assert.equal(a.tr.uid, b.tr.uid, 'two sessions, one user'); assert.notEqual(a.tr.sid, b.tr.sid); assert.match(a.tr.uid, /^[a-f0-9]{32}$/); assert.equal(store.get(TR.ANALYTICS_STORAGE.userId), a.tr.uid); assert.notEqual(mkTracker().tr.uid, a.tr.uid, 'another profile is another user'); assert.equal(TR.loadOrCreateUserId(memoryStore({ [TR.ANALYTICS_STORAGE.userId]: 'garbage' })).length, 32, 'a damaged id is replaced');
  const blocked = { get: () => null, set: () => false, remove: () => {}, keys: () => [] }; const x = mkTracker({ store: blocked }); assert.match(x.tr.uid, /^[a-f0-9]{32}$/, 'blocked storage: the id lives for the page session'); const thr = { get: () => { throw new Error('boom'); }, set: () => { throw new Error('boom'); }, remove: () => { throw new Error('boom'); }, keys: () => [] }; assert.doesNotThrow(() => mkTracker({ store: thr }), 'a storage that throws never breaks the tracker');
});
