test('V17.7.3 tracker — active time is sent as "active" events: hidden / idle time is excluded, a minute of use is sent together, no event is sent for less than a second', async () => {
  const m = mkTracker(); m.tr.start(true, true); m.clock.mono = 20_000; m.tr.interaction(); m.clock.mono = 40_000; m.tr.interaction(); m.clock.wall += 40_000; m.tr.setVisible(false); await new Promise((r) => setTimeout(r, 5)); const active = m.sent.flatMap((s) => s.batch).filter((e) => e.t === 'active'); assert.deepEqual(active.map((e) => e.ms), [40_000]);
  m.clock.mono = 1_000_000; m.clock.wall += 960_000; m.tr.setVisible(true); m.clock.mono = 1_100_000; m.tr.tick(); await m.tr.flush(); assert.equal(m.sent.flatMap((s) => s.batch).filter((e) => e.t === 'active').length, 1, 'the 16 hidden minutes produced nothing');
  const idle = mkTracker({ config: { inactivityTimeout: 60 } }); idle.tr.start(true, true); idle.clock.mono = 3_600_000; await idle.tr.flush(); assert.deepEqual(idle.sent.flatMap((s) => s.batch).filter((e) => e.t === 'active').map((e) => e.ms), [60_000], 'an hour of idle open page = at most one inactivity timeout');
  const tiny = mkTracker(); tiny.tr.start(true, true); tiny.clock.mono = 600; await tiny.tr.flush(); assert.equal(tiny.sent.flatMap((s) => s.batch).filter((e) => e.t === 'active').length, 0); const long = mkTracker({ config: { inactivityTimeout: 3600 } }); long.tr.start(true, true); long.clock.mono = 3_000_000; await long.tr.flush(); assert.deepEqual(long.sent.flatMap((s) => s.batch).filter((e) => e.t === 'active').map((e) => e.ms), [900_000, 900_000, 900_000, 300_000], 'split into events the service accepts');
});
test('V17.7.3 tracker — failures never reach the application: an unreachable service is retried with back-off, a permanent refusal drops the batch, the queue is bounded and survives a closed tab, a throwing sink / storage is swallowed', async () => {
  const m = mkTracker(); m.tr.start(true, true); m.tr.feature('about'); m.set({ ok: false, permanent: false, reason: 'unreachable' }); await m.tr.flush(); assert.equal(m.tr.stats().failures, 1); assert.equal(m.tr.stats().queued, 2, 'nothing was lost'); const calls = m.sent.length; await m.tr.flush(); assert.equal(m.sent.length, calls, 'back-off: no new attempt right away'); m.clock.wall += 16_000; m.set({ ok: true }); await m.tr.flush(); assert.equal(m.tr.stats().queued, 0); assert.equal(m.tr.stats().failures, 0); assert.equal(m.tr.stats().sent, 2);
  const p = mkTracker(); p.tr.start(true, true); p.set({ ok: false, permanent: true, reason: 'refused (400)' }); await p.tr.flush(); assert.equal(p.tr.stats().queued, 0); assert.equal(p.tr.stats().dropped, 1, 'a refused batch is dropped, not retried forever');
  const q = mkTracker(); q.tr.start(true, true); for (let i = 0; i < 250; i += 1) q.tr.feature('about'); assert.equal(q.tr.stats().queued, 100, 'bounded queue'); assert.ok(q.tr.stats().dropped >= 150);
  const store = memoryStore(); const a = mkTracker({ store }); a.tr.start(true, true); a.tr.feature('schema'); a.set({ ok: false, permanent: false, reason: 'unreachable' }); await a.tr.flush(); assert.ok(store.get(TR.ANALYTICS_STORAGE.queue), 'the queue is kept in browser storage'); const b = mkTracker({ store }); assert.equal(b.tr.peek().some((e) => e.f === 'schema'), true, 'a new page session still has the unsent events'); assert.equal(b.tr.uid, a.tr.uid); b.clock.wall += 86_400_001 * 2; const c = mkTracker({ store: memoryStore({ [TR.ANALYTICS_STORAGE.queue]: JSON.stringify([{ eid: 'old', ts: 1 }]) }) }); assert.equal(c.tr.peek().length, 0, 'events older than a day are not resurrected');
  for (const sink of [{ send: async () => { throw new Error('network'); } }, { send: () => { throw new Error('sync boom'); } }]) { const x = mkTracker({ sink }); x.tr.start(true, true); await assert.doesNotReject(x.tr.flush()); await assert.doesNotReject(x.tr.stop()); } let e; assert.doesNotThrow(() => { e = mkTracker({ store: { get: () => null, set: () => { throw new Error('quota'); }, remove: () => { throw new Error('quota'); }, keys: () => [] } }); }); assert.doesNotThrow(() => { e.tr.start(true, true); e.tr.feature('about'); e.tr.generation('cr', true); e.tr.interaction(); e.tr.tick(); });
  const s = mkTracker(); s.tr.start(true, true); await s.tr.stop(); assert.ok(s.sent.at(-1).o.exit === true && s.sent.at(-1).batch.some((x) => x.t === 'session_end'), 'a last best-effort send at the end of the session'); const hs = mkTracker(); hs.set({ ok: true, handedOff: true }); hs.tr.start(true, true); hs.tr.feature('about'); await hs.tr.stop(); assert.ok(hs.tr.stats().queued >= 3, 'handed to the beacon = not acknowledged: the events stay queued'); const again = mkTracker({ store: hs.store }); assert.ok(again.tr.peek().some((x) => x.t === 'session_end'), 'the next page session still has them and sends them with a normal request (the service ignores a repeated event id)'); s.tr.feature('about'); assert.equal(s.tr.peek().filter((x) => x.f === 'about').length, 0, 'a stopped tracker records nothing');
});
test('V17.7.3 telemetry sink — POSTs text/plain JSON to /v1/events without credentials; uses sendBeacon at exit; maps permanent refusals; every failure is a result, never an exception', async () => {
  const seen = []; const mkFetch = (status) => async (url, init) => { seen.push({ url, init }); return { ok: status >= 200 && status < 300, status }; }; const evs = [{ v: 1, eid: 'e1', t: 'session_start', ts: 1, uid: UID_A, sid: sid(1), ver: '1' }];
  assert.deepEqual(await new TR.ServiceTelemetrySink('https://an.example.org', mkFetch(200)).send(evs), { ok: true }); const c = seen[0]; assert.equal(c.url, 'https://an.example.org/v1/events'); assert.equal(c.init.method, 'POST'); assert.equal(c.init.credentials, 'omit'); assert.match(c.init.headers['Content-Type'], /^text\/plain/); assert.deepEqual(JSON.parse(c.init.body), { events: evs }); assert.ok(!('Authorization' in c.init.headers));
  assert.deepEqual(await new TR.ServiceTelemetrySink('https://an.example.org', mkFetch(400)).send(evs), { ok: false, permanent: true, reason: 'refused (400)' }); assert.equal((await new TR.ServiceTelemetrySink('https://an.example.org', mkFetch(503)).send(evs)).permanent, false); assert.equal((await new TR.ServiceTelemetrySink('https://an.example.org', async () => { throw new Error('net'); }).send(evs)).ok, false);
  let beaconed = null; const r = await new TR.ServiceTelemetrySink('https://an.example.org', mkFetch(200), (u, b) => { beaconed = { u, type: b.type }; return true; }).send(evs, { exit: true }); assert.deepEqual(r, { ok: true, handedOff: true }); assert.equal(beaconed.u, 'https://an.example.org/v1/events'); assert.match(beaconed.type, /^text\/plain;charset=utf-8$/i); const n = seen.length; await new TR.ServiceTelemetrySink('https://an.example.org', mkFetch(200), () => false).send(evs, { exit: true }); assert.equal(seen.length, n + 1, 'a refused beacon falls back to fetch');
});

