  const k = sum.data.kpi; assert.equal(k.uniqueUsers, 1, 'two sessions, one device → one unique user'); assert.equal(k.totalSessions, 2); assert.equal(k.totalActiveMs, 90_000, '2 × 45 s of active use'); assert.deepEqual([k.generated, k.successful, k.failed, k.successRate], [4, 2, 2, 50]); assert.deepEqual(sum.data.features.map((f) => [f.id, f.count]), [['describe-read-only', 2], ['quick-start', 2]]); assert.deepEqual(sum.data.versions, [{ version: '17.7.3', sessions: 2, users: 1 }]);
  assert.ok(!JSON.stringify(w.svc._store()).includes(secretSql) && !w.seen.join('').includes('SECRET_COLUMN')); const bad = await client.login('wrong-wrong-wrong-1'); assert.deepEqual([bad.ok, bad.kind, bad.message], [false, 'invalid', 'Invalid administrator password']); await client.logout(login.token); assert.equal((await client.summary(login.token, '2026-11-09', '2026-11-09')).kind, 'session');
