  const cases = [[429, { error: 'locked', retryAfterSeconds: 90 }, 'locked'], [429, { error: 'rate-limited' }, 'rate-limited'], [503, { error: 'admin-not-configured' }, 'not-configured'], [403, { error: 'origin-not-allowed' }, 'origin'], [500, { error: 'internal' }, 'unexpected'], [200, { nothing: true }, 'unexpected'], [200, '<html>', 'unexpected'], [200, 'not json', 'unexpected']];
