test('V17.7.3 the administrator password is not in the client: no literal, no hash, no storage of a password or token, no console output, no public configuration key for it; the bundle and the release carry none of the test values', () => {
  const clientFiles = ['src/v17/services/analyticsConfig.ts', 'src/v17/services/analyticsTracker.ts', 'src/v17/services/analyticsAdmin.ts', 'src/v17/services/analyticsView.ts', 'src/ui/analyticsRuntime.ts', 'src/ui/pages/analyticsPage.ts'];
  for (const f of clientFiles) { const raw = src(f); const t = strip(raw); assert.ok(!/console\./.test(t), `${f}: no console output`); assert.ok(!/scrypt\$|\bbcrypt\b|\bpbkdf2\b|createHash|subtle\.digest/i.test(t), `${f}: no hash or KDF in the client — the password is checked by the service`); assert.ok(!/(password|passwd|pwd|secret)\w*\s*[:=]\s*['"`][^'"`\s]{4,}['"`]/i.test(t), `${f}: no password literal`); assert.ok(!/\beval\(|new Function|document\.write/.test(t)); assert.ok(!/gh[pousr]_[A-Za-z0-9]{20,}|github_pat_|sk-[A-Za-z0-9]{20,}/.test(raw)); }
  for (const f of ['src/v17/services/analyticsAdmin.ts', 'src/ui/analyticsRuntime.ts', 'src/ui/pages/analyticsPage.ts']) { const t = strip(src(f)); assert.ok(!/(localStorage|sessionStorage)/.test(t), `${f}: the session token and the password are never stored (a reload requires signing in again)`); assert.ok(!/(store|kv)\.(set|setItem)\(/.test(t), `${f}: no store write`); assert.ok(!/location\.(hash|search|href)\s*=|history\.(push|replace)State|document\.cookie/.test(t), `${f}: nothing in the URL or a cookie`); }
  const page = strip(src('src/ui/pages/analyticsPage.ts')); assert.ok(!/\.value\s*=\s*[^;]*\b(pw|value|a|b2)\b[^;]*\bstore\b/.test(page)); assert.match(page, /then\(\(r\) => \{\s*pw\.value = '';/, 'the password field is cleared after every attempt'); assert.match(page, /type="password"/); assert.ok(!/innerHTML\s*=[^;]*\$\{\s*(pw|password|value)\b/.test(page), 'the password is never written into markup');
  const cfgDoc = src('docs/ANALYTICS.md'); assert.ok(!/adminPassword["']?\s*:/.test(cfgDoc.replace(/NEVER[^\n]*|must not[^\n]*|not[^\n]*/gi, '')), 'no documented public configuration key for the password');
  for (const f of ['dist/index.html', 'index.html', 'release/index.html']) if (existsSync(join(root, f))) { const h = src(f); for (const v of [PW, PW2, 'SYNTHETIC-', 'admin-credential', 'analytics-store']) assert.ok(!h.includes(v), `${f}: no ${v}`); assert.ok(!/scrypt\$\d/.test(h), `${f}: no password hash`); assert.ok(h.includes('analytics.config.json'), `${f}: reads the deployed configuration`); }
  assert.ok(!existsSync(join(root, 'sql-assistant-data/analytics.config.json')) || !/password|secret|hash|token/i.test(src('sql-assistant-data/analytics.config.json')), 'a committed configuration file holds no secret'); assert.ok(!existsSync(join(root, 'release/sql-assistant-data/analytics.config.json')), 'release/ ships NO configuration: analytics is off until an administrator deploys one');
});
test('V17.7.3 analytics never blocks or breaks SQL Assistant: start-up is fire-and-forget; the runtime functions swallow every failure; the tracking calls are no-ops when analytics is off; the hooks record only outcomes', async () => {
  const main = strip(src('src/main.ts')); assert.match(main, /void startAnalytics\(\)\.then\(/); assert.ok(!/await\s+startAnalytics/.test(main), 'start-up never waits for analytics'); assert.ok(main.indexOf('startAnalytics()') > main.indexOf('startGithubConnection();'));
  const rt = await imp('ui/analyticsRuntime.js').catch((e) => ({ err: e })); if (rt.err) { assert.match(String(rt.err), /document|window|localStorage|indexedDB|navigator/i, 'the runtime needs a browser (covered by the browser suite)'); } else { assert.doesNotThrow(() => { rt.trackFeature('about'); rt.trackGeneration('cr', true); rt.lockAnalytics('manual'); }); }
  for (const [f, fn, kinds] of [['src/ui/pages/describeNeed.ts', 'trackGeneration', ["'describe-read-only'", "'describe-cr'"]], ['src/ui/pages/readonly.ts', 'trackGeneration', ["'read-only'"]], ['src/ui/pages/other.ts', 'trackGeneration', ["'cr'"]]]) { const t = src(f); assert.ok(t.includes(fn), f); for (const k of kinds) assert.ok(t.includes(`trackGeneration(${k}`), `${f} records ${k}`); }
  const hooks = ['describeNeed.ts', 'readonly.ts', 'other.ts'].map((f) => src(`src/ui/pages/${f}`)).join('\n'); for (const call of hooks.match(/trackGeneration\([^;]*\);/g)) assert.ok(!/generatedSql\)|\.sql\b|state\.generated|text\)/.test(call.replace(/generatedSql\.trim\(\)/g, '')), `a generation hook passes no SQL or text: ${call.slice(0, 90)}`);
  for (const call of hooks.match(/trackFeature\([^)]*\)/g)) assert.match(call, /trackFeature\('(copy-sql|accept-learn)'\)/);
  assert.match(main, /FEATURE_OF/); for (const r of ['quickstart', 'readonly', 'cr', 'describe-readonly', 'describe-cr', 'query-add', 'query-library', 'schema-used', 'github', 'error-rectifier', 'settings', 'about']) assert.ok(new RegExp(`['"]?${r}['"]?:`).test(main.slice(main.indexOf('FEATURE_OF'), main.indexOf('FEATURE_OF') + 900)), r); assert.ok(!/analytics:\s*'/.test(main.slice(main.indexOf('FEATURE_OF'), main.indexOf('FEATURE_OF') + 900)), 'the Analytics page itself is not tracked');
});
test('V17.7.3 navigation: the Analytics route exists, is mapped, and appears in the hamburger menu (with the lock state); every previous route and menu item is still there; the dashboard is not reachable without the dialog', async () => {
  const S = await imp('ui/state.js'); for (const r of ['quickstart', 'readonly', 'cr', 'schema-used', 'error-rectifier', 'settings', 'about', 'github', 'query-add', 'query-library', 'describe-readonly', 'describe-cr', 'analytics']) assert.ok(S.ROUTES.includes(r), r); assert.equal(S.ROUTES.length, 13);
  const nav = src('src/ui/components/navbar.ts'); assert.match(nav, /\{ id: 'analytics', label: 'Analytics', icon: 'bar-chart'/); assert.ok(nav.indexOf("id: 'error-rectifier'") < nav.indexOf("id: 'analytics'") && nav.indexOf("id: 'analytics'") < nav.indexOf("id: 'settings'")); for (const old of ["id: 'readonly'", "id: 'cr'", "id: 'describe-readonly'", "id: 'query-add'", "id: 'query-library'", "id: 'schema-used'", "id: 'github'", "id: 'settings'", "id: 'about'"]) assert.ok(nav.includes(old), old);
  assert.match(src('src/main.ts'), /analytics: \(\) => renderAnalyticsPage\(main, navigate\)/); const page = strip(src('src/ui/pages/analyticsPage.ts')); const entry = page.slice(page.indexOf('export function renderAnalyticsPage')); assert.match(entry, /if \(!isAnalyticsUnlocked\(\)\) \{\s*showAuth\(\);/, 'the dialog is opened when the page is opened while locked'); assert.match(page, /function draw\(\): void \{ if \(!isAnalyticsUnlocked\(\)\) \{ locked\(\); return; \} dashboard\(\);/, 'the dashboard is rendered only for an unlocked session'); assert.ok(!/fetchAnalyticsSummary/.test(page.slice(0, page.indexOf('function dashboard'))) || /async function load/.test(page), 'data is requested only by load()');
  assert.equal((page.match(/fetchAnalyticsSummary\(/g) || []).length, 1, 'ONE place requests the numbers, and only from the dashboard'); assert.match(page, /Administrator Authentication/); assert.match(page, /type="password"/); assert.match(strip(src('src/v17/services/analyticsAdmin.ts')), /Invalid administrator password/);
});

