test('V17.7.3 deployment: the analytics configuration is written next to index.html by the Pages workflow from repository VARIABLES (not secrets); the service has its own credential-free packaging workflow (V17.7.5: no secret, nothing deployed); publish-data never copies *.config.json', () => {
  const pages = src('.github/workflows/deploy-pages.yml'); assert.match(pages, /analytics\.config\.json/); assert.match(pages, /SQLA_ANALYTICS_URL/); assert.match(pages, /vars\.SQLA_ANALYTICS_URL != ''/); assert.ok(!/secrets\.SQLA_ANALYTICS/.test(pages), 'the Pages workflow (public output) never touches the password secret'); assert.ok(pages.indexOf('analytics.config.json') < pages.indexOf('Verify the artifact that will be published'), 'written before the final artifact verification');
  const dep = src('.github/workflows/package-analytics-service.yml'); assert.ok(!/secrets\./.test(dep), 'V17.7.5: the packaging workflow reads no secret — the password hash is set on the operator\'s own host'); assert.ok(!/continue-on-error/.test(dep.replace(/^\s*#.*$/gm, ''))); assert.match(dep, /--self-test/); assert.match(dep, /upload-artifact@v4/); assert.match(dep, /permissions: \{ contents: read \}/); assert.match(dep, /actions\/checkout@v5/); assert.match(dep, /actions\/setup-node@v5/);
  assert.match(src('scripts/publish-data.mjs'), /\\\.config\\\.json|\.config\.json/); assert.ok(!existsSync(join(root, 'release/sql-assistant-data/analytics.config.json')));
  const pkg = JSON.parse(src('package.json')); for (const k of ['analytics', 'analytics:set-admin-password', 'analytics:hash-password']) assert.ok(pkg.scripts[k], k); assert.match(pkg.scripts['test:browser'], /browser_test_v1773\.py/); assert.ok(existsSync(join(root, 'scripts/browser_test_v1773.py')), 'the V17.7.3 browser suite is part of the package');
  assert.ok(!pkg.dependencies, 'the service has no dependencies'); const svcSrc = src('server/analytics-service.mjs'); for (const m of svcSrc.matchAll(/from '([^']+)'/g)) assert.match(m[1], /^node:/, `only Node built-ins: ${m[1]}`);
});
