  const { sourceSet } = awaitedSourceSet; const ss = sourceSet(root); for (const f of ['analyticsConfig', 'analyticsTracker', 'analyticsAdmin', 'analyticsView']) assert.ok(ss.files.some((x) => x.endsWith(`v17/services/${f}.ts`)), `${f} is reached from src/main.ts`); for (const f of ['ui/analyticsRuntime', 'ui/pages/analyticsPage']) assert.ok(ss.files.some((x) => x.endsWith(`${f}.ts`)), f); assert.ok(!ss.orphans.some((x) => /analytics/i.test(x)), 'no analytics file is an orphan');
